// A device token belongs to the SIGNED-IN user, so pushes follow the account
// and stop following it after sign-out. Same HMAC check as the hook/auth-me.
const crypto = require('crypto');
const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const token = String(headers['x-user-token'] || headers['X-User-Token'] || '').trim();
const secret = $env.AUTH_TOKEN_SECRET || '';
let uid = '';
if (token && secret) {
  try {
    const parts = token.split('.');
    if (parts.length === 3 && parts[0] === 'v1') {
      const expected = crypto.createHmac('sha256', secret).update(parts[1]).digest('base64url');
      const a = Buffer.from(parts[2]);
      const b = Buffer.from(expected);
      if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
        const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString());
        if (payload.uid && payload.exp * 1000 > Date.now()) uid = String(payload.uid);
      }
    }
  } catch (e) {
    uid = '';
  }
}
return [{ json: {
  uid,
  fcm_token: String(body.token || '').trim(),
  platform: String(body.platform || 'android').trim() || 'android',
  device_name: String(body.device_name || '').trim(),
} }];

// Registered only when the caller already has a company (setup complete).
// briefing_time is read for THAT company, never the legacy id = 1.
const row = $input.first()?.json || {};
const scope = $('Verify Session Token').first().json || {};
const registered = row.company_id !== undefined && row.company_id !== null;
return [{ json: {
  ok: true,
  registered,
  company_id: row.company_id ?? null,
  user_id: scope.uid || null,
  note: registered ? null : 'no company yet - register again after setup',
} }];

