// Merge the registration result with the company's briefing time.
const reg = $('Shape Response').first().json || {};
const bt = $input.first()?.json || {};
return [{ json: {
  status: 'ok',
  ok: true,
  registered: !!reg.registered,
  company_id: reg.company_id ?? null,
  user_id: reg.user_id ?? null,
  note: reg.note ?? null,
  briefing_time: bt.briefing_time ?? null,
} }];
